<?php if(!defined('ABSPATH'))exit;global $wpdb;
$tv=ICD_Visitas_Database::table('visitas');$te=ICD_Visitas_Database::table('escolas');$tm=ICD_Visitas_Database::table('mediadores');$tp=ICD_Visitas_Database::table('participantes');$tpg=ICD_Visitas_Database::table('pedagogas');$tvp=ICD_Visitas_Database::table('visita_pedagogas');$tvin=ICD_Visitas_Database::table('vinculos');
$schools=$wpdb->get_results("SELECT id,nome FROM $te WHERE ativo=1 ORDER BY nome");$meds=$wpdb->get_results("SELECT id,nome FROM $tm WHERE ativo=1 ORDER BY nome");$peds=$wpdb->get_results("SELECT id,nome FROM $tpg WHERE ativo=1 ORDER BY nome");
$rows=$wpdb->get_results("SELECT v.*,e.nome escola,(SELECT GROUP_CONCAT(m.nome SEPARATOR ', ') FROM $tp p JOIN $tm m ON m.id=p.mediador_id WHERE p.visita_id=v.id) mediadores,(SELECT GROUP_CONCAT(pg.nome SEPARATOR ', ') FROM $tvp vp JOIN $tpg pg ON pg.id=vp.pedagoga_id WHERE vp.visita_id=v.id) pedagogas FROM $tv v JOIN $te e ON e.id=v.escola_id ORDER BY v.data_visita DESC,v.id DESC LIMIT 200");
$map=[];foreach($wpdb->get_results("SELECT escola_id,mediador_id FROM $tvin WHERE ativo=1") as $x)$map[$x->mediador_id][]=(int)$x->escola_id;
$editId=absint($_GET['edit']??0);$editing=null;$editMeds=[];$editPeds=[];if($editId){$editing=$wpdb->get_row($wpdb->prepare("SELECT * FROM $tv WHERE id=%d",$editId));if($editing){$editMeds=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT mediador_id FROM $tp WHERE visita_id=%d",$editId)));$editPeds=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT pedagoga_id FROM $tvp WHERE visita_id=%d",$editId)));}}?>
<div class="wrap icd-admin"><h1>Visitas pedagógicas</h1><p>A pedagoga realiza a visita. Os mediadores selecionados são os profissionais acompanhados naquela escola.</p><?php if($editing):?><div class="notice notice-info inline"><p><strong>Editando visita #<?php echo (int)$editing->id;?></strong> — altere os dados abaixo e clique em Atualizar visita. <a href="<?php echo esc_url(ICD_Visitas_Helpers::page_url('icd-visitas-registros'));?>">Cancelar edição</a></p></div><?php endif;?><form class="icd-form-grid" method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>"><?php wp_nonce_field('icd_save_visita');?><input type="hidden" name="action" value="icd_save_visita"><?php if($editing):?><input type="hidden" name="id" value="<?php echo (int)$editing->id;?>"><?php endif;?><label>Escola<select required name="escola_id" id="icd-school"><option value="">Selecione</option><?php foreach($schools as $x)echo '<option value="'.$x->id.'" '.selected($editing?$editing->escola_id:0,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Data<input required type="date" name="data_visita" value="<?php echo esc_attr($editing?$editing->data_visita:current_time('Y-m-d'));?>"></label><label>Turno<select name="turno"><?php foreach(['manha'=>'Manhã','tarde'=>'Tarde','noite'=>'Noite','integral'=>'Integral'] as $k=>$lab)echo '<option value="'.$k.'" '.selected($editing?$editing->turno:'manha',$k,false).'>'.$lab.'</option>';?></select></label><label>Status<select name="status"><?php foreach(['realizada','programada','confirmada','cancelada','reagendada','nao_realizada'] as $st)echo '<option value="'.$st.'" '.selected($editing?$editing->status:'realizada',$st,false).'>'.esc_html(ICD_Visitas_Helpers::status_label($st)).'</option>';?></select></label><input type="hidden" name="tipo" value="acompanhamento"><fieldset class="full"><legend>Pedagoga(s) que realizou(aram) a visita</legend><div class="icd-check-grid"><?php foreach($peds as $x):?><label class="icd-check"><input type="checkbox" name="pedagogas[]" value="<?php echo (int)$x->id;?>" <?php checked(in_array((int)$x->id,$editPeds,true));?>> <?php echo esc_html($x->nome);?></label><?php endforeach;?></div></fieldset><fieldset class="full"><legend>Mediadores acompanhados</legend><p class="description">Ao escolher a escola, ficam visíveis apenas os mediadores vinculados a ela.</p><div class="icd-check-grid"><?php foreach($meds as $x):$ids=implode(',',array_map('intval',$map[$x->id]??[]));?><label class="icd-check icd-mediator-option" data-schools="<?php echo esc_attr($ids);?>"><input type="checkbox" name="mediadores[]" value="<?php echo (int)$x->id;?>" <?php checked(in_array((int)$x->id,$editMeds,true));?>> <?php echo esc_html($x->nome);?></label><?php endforeach;?></div></fieldset><label class="full">Observações da visita<textarea name="observacoes" rows="5" placeholder="Registre o que foi observado, orientações dadas, pontos de atenção, avanços e encaminhamentos."><?php echo esc_textarea($editing?$editing->observacoes:'');?></textarea></label><button class="button button-primary"><?php echo $editing?'Atualizar visita':'Registrar visita';?></button></form>
<div class="icd-table-wrap"><table class="widefat striped"><thead><tr><th>Data</th><th>Escola</th><th>Pedagoga</th><th>Mediadores acompanhados</th><th>Turno</th><th>Status</th><th>Observações</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?php echo esc_html(date_i18n('d/m/Y',strtotime($x->data_visita)));?></td><td><?php echo esc_html($x->escola);?></td><td><?php echo esc_html($x->pedagogas?:'—');?></td><td><?php echo esc_html($x->mediadores?:'—');?></td><td><?php echo esc_html(ICD_Visitas_Helpers::turno_label($x->turno));?></td><td><span class="icd-status icd-status-<?php echo esc_attr($x->status);?>"><?php echo esc_html(ICD_Visitas_Helpers::status_label($x->status));?></span></td><td><?php echo esc_html(wp_trim_words($x->observacoes,14,'…'));?></td><td class="icd-actions"><a class="button button-small" href="<?php echo esc_url(ICD_Visitas_Helpers::page_url('icd-visitas-registros', ['edit' => (int) $x->id]));?>">Editar</a><form method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>" onsubmit="return confirm('Excluir esta visita? Esta ação não pode ser desfeita.');"><?php wp_nonce_field('icd_delete_visita_'.$x->id);?><input type="hidden" name="action" value="icd_delete_visita"><input type="hidden" name="id" value="<?php echo (int)$x->id;?>"><input type="hidden" name="redirect_to" value="<?php echo esc_url(ICD_Visitas_Helpers::page_url('icd-visitas-registros'));?>"><button class="button button-small icd-danger" type="submit">Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){const s=document.getElementById('icd-school');const opts=[...document.querySelectorAll('.icd-mediator-option')];function f(){const id=s.value;opts.forEach(o=>{const ok=id&&o.dataset.schools.split(',').includes(id);o.style.display=ok?'flex':'none';if(!ok)o.querySelector('input').checked=false;});}if(s){s.addEventListener('change',f);f();}});</script>
